import{_ as t,o as n,c as i,a3 as a}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Ansichten und Auswertungen einbetten","description":"Grid-Ansichten, Kennzahlen und Diagramme auf einer Seite darstellen.","frontmatter":{"title":"Ansichten und Auswertungen einbetten","description":"Grid-Ansichten, Kennzahlen und Diagramme auf einer Seite darstellen."},"headers":[],"relativePath":"seiten/auswertungen.md","filePath":"seiten/auswertungen.md","lastUpdated":1788108473000}'),r={name:"seiten/auswertungen.md"};function s(l,e,d,o,u,h){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="ansichten-und-auswertungen-einbetten" tabindex="-1">Ansichten und Auswertungen einbetten <a class="header-anchor" href="#ansichten-und-auswertungen-einbetten" aria-label="Permalink to &quot;Ansichten und Auswertungen einbetten&quot;">​</a></h1><p>Diese Blöcke bringen Daten aus Ihren Grids auf die Seite — als Tabelle, als Kennzahl oder als Diagramm.</p><hr><h2 id="grid-ansicht" tabindex="-1">Grid Ansicht <a class="header-anchor" href="#grid-ansicht" aria-label="Permalink to &quot;Grid Ansicht&quot;">​</a></h2><p>Bettet eine bestehende <a href="/ansichten/was-ist-eine-ansicht">Ansicht</a> ein. Der wichtigste Block für Portale.</p><p>Auswahl über <em>Legen Sie die Grid Ansicht fest</em> → <strong>Ansicht auswählen</strong>.</p><h3 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Volle Breite anzeigen</strong></td><td>Über die gesamte Seitenbreite</td></tr><tr><td><strong>Suche anzeigen</strong></td><td>Suchfeld für Besucher</td></tr><tr><td><strong>Filter anzeigen</strong></td><td>Filter für Besucher</td></tr><tr><td><strong>CSV-Download anzeigen</strong></td><td>Export für Besucher</td></tr><tr><td><strong>Einträge nur lesbar</strong></td><td>Verhindert Bearbeitung</td></tr><tr><td><strong>Detailansicht nicht öffnen</strong></td><td>Klick auf eine Zeile öffnet nichts</td></tr><tr><td><strong>Titel ausblenden</strong></td><td>Blendet den Ansichtstitel aus</td></tr><tr><td><strong>Button Farbe</strong></td><td>Farbe der Bedienelemente</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Für ein reines Anzeige-Portal beide Schalter setzen</p><p><em>Einträge nur lesbar</em> allein genügt nicht — Besucher gelangen weiterhin in die Detailansicht eines Eintrags und sehen dort <strong>alle</strong> Felder, auch die in der Ansicht ausgeblendeten.</p><p>Setzen Sie zusätzlich <strong>Detailansicht nicht öffnen</strong>.</p></div><div class="warning custom-block"><p class="custom-block-title">CSV-Download bewusst freigeben</p><p>Ist <em>CSV-Download anzeigen</em> aktiv, können Besucher den gesamten sichtbaren Datenbestand herunterladen — nicht nur ansehen. Bei personenbezogenen Daten sollte das ausgeschaltet bleiben.</p></div><div class="tip custom-block"><p class="custom-block-title">Eigene Ansicht fürs Portal</p><p>Betten Sie nicht Ihre Arbeitsansicht ein. Legen Sie eine Kopie an, blenden Sie interne Spalten aus und filtern Sie auf das Freizugebende. So ändert sich das Portal nicht versehentlich mit, wenn Sie intern etwas anpassen.</p></div><hr><h2 id="zahler" tabindex="-1">Zähler <a class="header-anchor" href="#zahler" aria-label="Permalink to &quot;Zähler&quot;">​</a></h2><blockquote><p><em>Zähle die Anzahl der Einträge in einer Ansicht</em></p></blockquote><p>Zeigt eine einzelne Zahl. Die Grundlage ist eine Ansicht — deren Filter bestimmt, was gezählt wird.</p><div class="tip custom-block"><p class="custom-block-title">Filter macht die Kennzahl</p><p>Ein Zähler auf einer ungefilterten Ansicht zeigt nur „wie viele Einträge gibt es&quot;. Interessant wird er mit Filter: „offene Anfragen&quot;, „überfällige Aufgaben&quot;, „Neuzugänge diesen Monat&quot;.</p><p>Legen Sie je Kennzahl eine eigene, entsprechend gefilterte Ansicht an.</p></div><hr><h2 id="summenkarte" tabindex="-1">Summenkarte <a class="header-anchor" href="#summenkarte" aria-label="Permalink to &quot;Summenkarte&quot;">​</a></h2><blockquote><p><em>Summiert die Werte einer numerischen Spalte in einer Ansicht</em></p></blockquote><p>Einstellung: <strong>Zu summierende Spalte</strong>.</p><p>Meldungen:</p><table tabindex="0"><thead><tr><th>Meldung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><em>Diese Ansicht hat keine summierbaren numerischen Spalten</em></td><td>Es fehlt eine Spalte vom Typ Zahl, Kommazahl oder Währung — oder sie ist in der Ansicht ausgeblendet</td></tr><tr><td><em>Diese Ansicht hat mehr als {maxRows} Zeilen. Die Summe umfasst nur die ersten {maxRows} Zeilen.</em></td><td>Die Summe ist <strong>unvollständig</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Bei großen Ansichten ist die Summe unvollständig</p><p>Ab einer bestimmten Zeilenzahl summiert der Block nur den Anfang der Ansicht — und zeigt trotzdem eine Zahl an.</p><p>Für belastbare Gesamtsummen nehmen Sie stattdessen eine <a href="/ansichten/filtern-sortieren-gruppieren">Gruppierung mit Aggregat</a> oder ein Feld vom Typ <a href="/grids/berechnete-felder">Summe berechnen</a>.</p></div><hr><h2 id="donut-diagramm" tabindex="-1">Donut-Diagramm <a class="header-anchor" href="#donut-diagramm" aria-label="Permalink to &quot;Donut-Diagramm&quot;">​</a></h2><blockquote><p><em>Zeigt die Verteilung der Werte einer Einzelauswahl-Spalte</em></p></blockquote><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Einzelauswahl</strong></td><td>Die auszuwertende Spalte</td></tr><tr><td><strong>Legende anzeigen</strong></td><td>Beschriftung der Segmente</td></tr><tr><td><strong>Titel ändern</strong></td><td>Eigener Diagrammtitel</td></tr></tbody></table><p>Beim Titel gilt: <em>Überschreiben Sie den Diagrammtitel. Leer lassen, um den Spaltennamen zu verwenden.</em></p><p>Werte außerhalb der Optionen erscheinen als <strong>Sonstige</strong>.</p><p>Ohne passende Spalte: <em>Diese Ansicht hat keine Spalte vom Typ Einzelauswahl</em>.</p><div class="tip custom-block"><p class="custom-block-title">Nur für Einzelauswahl</p><p>Mehrfachauswahl, Text und Zahlen funktionieren nicht. Wollen Sie etwas anderes auswerten, legen Sie eine Einzelauswahl-Spalte an, die die gewünschte Kategorisierung abbildet.</p></div><hr><h2 id="terminprognose" tabindex="-1">Terminprognose <a class="header-anchor" href="#terminprognose" aria-label="Permalink to &quot;Terminprognose&quot;">​</a></h2><blockquote><p><em>Vergleicht geplante Termine mit aktuellen und früheren Schätzungen</em></p></blockquote><table tabindex="0"><thead><tr><th>Einstellung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Meilensteine</strong></td><td>Spalte mit den Bezeichnungen</td></tr><tr><td><strong>letzte Schätzung</strong></td><td>Spalte mit dem aktuellen Stand</td></tr></tbody></table><p>Die Darstellung unterscheidet <strong>Plan</strong> und <strong>aktuelle Schätzung</strong>. Ohne Angabe heißen Einträge <em>Meilenstein</em>.</p><p>Meldungen: <em>Diese Ansicht enthält keine Datumsspalten</em>, <em>Diese Ansicht enthält keine Zeilen</em>, <em>Es wurden keine gültigen Datumswerte gefunden</em>. Auch hier gilt eine Zeilenbegrenzung.</p><hr><h2 id="grid-liste" tabindex="-1">Grid Liste <a class="header-anchor" href="#grid-liste" aria-label="Permalink to &quot;Grid Liste&quot;">​</a></h2><blockquote><p><em>Erstelle eine Liste basierend auf Einträgen aus einem Grid</em></p></blockquote><p>Anders als die Grid-Ansicht gestalten Sie hier das Aussehen <strong>jedes Listeneintrags selbst</strong>: Sie wählen ein Grid (<em>Grid auswählen</em>) und bauen einen Vorlagenblock, der je Eintrag wiederholt wird (<em>Listen-Element bearbeiten</em>).</p><div class="tip custom-block"><p class="custom-block-title">Wenn eine Tabelle nicht passt</p><p>Für Portale, die keine Tabellenoptik haben sollen — Stellenanzeigen, Veranstaltungen, Produktlisten — ist dieser Block die Alternative. Sie können Bilder, Überschriften und Buttons frei anordnen.</p><p>Der Aufbau dauert länger als bei der Grid-Ansicht — dafür bestimmen Sie die Gestaltung vollständig selbst. Für rein interne Übersichten ist die Grid-Ansicht meist der schnellere Weg.</p></div><hr><h2 id="button-und-qr-code" tabindex="-1">Button und QR Code <a class="header-anchor" href="#button-und-qr-code" aria-label="Permalink to &quot;Button und QR Code&quot;">​</a></h2><p>Beide verweisen auf ein Formular oder einen Flow.</p><h3 id="button" tabindex="-1">Button <a class="header-anchor" href="#button" aria-label="Permalink to &quot;Button&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Auswahl</th></tr></thead><tbody><tr><td><strong>Link</strong></td><td>Das Ziel — <em>Link auswählen</em></td></tr><tr><td><strong>Öffnen</strong></td><td><em>Auf dieser Seite öffnen</em> / <em>In neuem Tab öffnen</em></td></tr><tr><td><strong>Nach dem Absenden</strong></td><td><em>Formular offen lassen</em> / <em>Nach 3 Sekunden schließen</em> / <em>Nach 5 Sekunden schließen</em></td></tr><tr><td><strong>Button Titel ändern</strong></td><td>Beschriftung</td></tr><tr><td><strong>Formular vorausfüllen</strong></td><td>Werte vorbelegen</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">„Auf dieser Seite öffnen&quot; wirkt integrierter</p><p>Das Formular erscheint dann im Portal selbst statt in einem neuen Tab. In Verbindung mit <em>Nach 3 Sekunden schließen</em> entsteht ein runder Ablauf: Button klicken, ausfüllen, absenden, zurück zur Seite.</p></div><p>→ <a href="/formulare/vorausgefuellte-links">Vorausgefüllte Links</a></p><h3 id="qr-code" tabindex="-1">QR Code <a class="header-anchor" href="#qr-code" aria-label="Permalink to &quot;QR Code&quot;">​</a></h3><p>Dasselbe Ziel als QR-Code — für Aushänge und gedrucktes Material.</p><hr><h2 id="ein-dashboard-zusammensetzen" tabindex="-1">Ein Dashboard zusammensetzen <a class="header-anchor" href="#ein-dashboard-zusammensetzen" aria-label="Permalink to &quot;Ein Dashboard zusammensetzen&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vertikales Layout</span></span>
<span class="line"><span>├── Überschrift 1                „Auftragslage&quot;</span></span>
<span class="line"><span>├── Horizontales Layout          (Wrap Content)</span></span>
<span class="line"><span>│   ├── Zähler                   Ansicht „offene Aufträge&quot;</span></span>
<span class="line"><span>│   ├── Summenkarte              Ansicht „offene Aufträge&quot;, Spalte Betrag</span></span>
<span class="line"><span>│   └── Donut-Diagramm           Ansicht „alle Aufträge&quot;, Spalte Status</span></span>
<span class="line"><span>└── Grid Ansicht                 Ansicht „offene Aufträge&quot;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Je Kennzahl eine Ansicht</p><p>Jeder Auswertungsblock bezieht sich auf <strong>eine</strong> Ansicht. Für vier Kennzahlen brauchen Sie also gegebenenfalls vier unterschiedlich gefilterte Ansichten. Benennen Sie sie sprechend — sonst wird das Dashboard später schwer zu pflegen.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/seiten/layout-bloecke">Layout-Blöcke</a></li><li><a href="/referenz/blocktypen">Blocktypen-Referenz</a></li><li><a href="/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></li></ul>`,57)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
